   964  int sam_index_build3(const char *fn, const char *fnidx, int min_shift, int nthreads)
   965  {
   966      hts_idx_t *idx;
   967      htsFile *fp;
   968      int ret = 0;
   969
   970      if ((fp = hts_open(fn, "r")) == 0) return -2;
   971      if (nthreads)
   972          hts_set_threads(fp, nthreads);
   973
   974      switch (fp->format.format) {
   975      case cram:
   976
   977          ret = cram_index_build(fp->fp.cram, fn, fnidx);
   978          break;
   979
   980      case bam:
   981      case sam:
   982          if (fp->format.compression != bgzf) {
   983              hts_log_error("%s file \"%s\" not BGZF compressed",
   984                            fp->format.format == bam ? "BAM" : "SAM", fn);
   985              ret = -1;
   986              break;
   987          }
   988          idx = sam_index(fp, min_shift);
   989          if (idx) {
   990              ret = hts_idx_save_as(idx, fn, fnidx, (min_shift > 0)? HTS_FMT_CSI : HTS_FMT_BAI);
   991              if (ret < 0) ret = -4;
   992              hts_idx_destroy(idx);
   993          }
   994          else ret = -1;
   995          break;
   996
   997      default:
   998          ret = -3;
   999          break;
  1000      }
  1001      hts_close(fp);
  1002
  1003      return ret;
  1004  }
